/* From Uiverse.io by Nawsome - Tags: checkbox */
.__UIV_SCOPE__ .clear {
  clear: both;
}

.__UIV_SCOPE__ .checkBox {
  display: block;
  cursor: pointer;
  width: 30px;
  height: 30px;
  border: 3px solid rgba(255, 255, 255, 0);
  border-radius: 10px;
  position: relative;
  overflow: hidden;
  box-shadow: 0px 0px 0px 2px #fff;
}

.__UIV_SCOPE__ .checkBox div {
  width: 60px;
  height: 60px;
  background-color: #fff;
  top: -52px;
  left: -52px;
  position: absolute;
  transform: rotateZ(45deg);
  z-index: 100;
}

.__UIV_SCOPE__ .checkBox input[type=checkbox]:checked + div {
  left: -10px;
  top: -10px;
}

.__UIV_SCOPE__ .checkBox input[type=checkbox] {
  position: absolute;
  left: 50px;
  visibility: hidden;
}

.__UIV_SCOPE__ .transition {
  transition: 300ms ease;
}
